stops = {'TAA','TAG','TGA'}
def orfs(t):
    out = []
    for frame in range(3):
        last_stop = None
        start = frame
        for i in range(frame, len(t)-2, 3):
            if t[i:i+3] in stops:
                out.append((start, i+3, i - start))
                start = i+3
        out.append((start, len(t)-((len(t)-frame)%3), (len(t)-((len(t)-frame)%3))-start if len(t)>start else 0))
    return [o for o in out if o[2] > 90]

